const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";
const groups = JSON.parse(await fs.readFile(S+"\\_GIG50_CLEAN.json","utf8"));

// 去重：同平台多域名只留一个
const DEDUP = {
  "braintrust.com": "usebraintrust.com",  // 保留后者
  "huntr.com": "huntr.co",
  "freelancer.co.nz": "freelancer.com",
  "freelancer.com.au": "freelancer.com",
  "freelancer.in": "freelancer.com",
};
const seen = new Set();
const final = [];
for (const g of groups) {
  const items = [];
  for (const it of g.items) {
    const h = String(it.host).toLowerCase();
    const canon = DEDUP[h] || h;
    if (seen.has(canon)) continue;
    seen.add(canon);
    items.push({...it, host: h});
  }
  if (items.length) final.push({cat:g.cat, items});
}
const total = final.reduce((s,g)=>s+g.items.length,0);

// 详细数据（含实测信号）
const [a,b] = await Promise.all([
  fs.readFile(S+"\\_GIG50_RESULT.json","utf8").then(JSON.parse).catch(()=>[]),
  fs.readFile(S+"\\_GIG_EXTRA_RESULT.json","utf8").then(JSON.parse).catch(()=>[])
]);
const detail = {};
for (const o of [...a,...b]) detail[String(o.host).toLowerCase()] = o;

const rows=[];
const add=s=>rows.push(s);
add("---"); add("date: 2026-10-21"); add("tags: [工作, 搞钱, 接单平台, 50个, 实测验证, 重要]"); add("---"); add("");
add("# 50 个真实可用的接单/散活平台（实测验证版）");
add("");
add("> **目标：50 个能真正接到活的信息平台，国内外都行，单价高低不论，能同时盯多个、有活就干。**");
add("> **方法：2026-10-21 逐个 HTTP 实测，能打开且有项目/任务信号的才收录。**");
add("> **共实测 132 个候选，收录 **"+total+"** 个可用平台。**");
add("");
add("## 一、⭐⭐ 怎么用这份清单");
add("");
add("| 你要做的事 | 怎么做 |");
add("|---|---|");
add("| **每天扫一遍** | 挑 5-8 个重点平台，早上各看一次有没有新活 |");
add("| **优先注册** | 顺序：Fiverr → Freelancer → 各区域站 → 赏金/AI标注 |");
add("| **判断有没有活** | 本清单已标注「有活有价」= 能看到项目+预算；「有活无价」= 有项目但要登录看价 |");
add("| **门槛最低的** | 微任务类（Clickworker/Microworkers/Toloka）+ 用户测试（UserTesting 等） |");
add("");
add("## 二、⭐⭐ 分类清单（"+total+" 个）");
add("");

let globalIdx = 1;
for (const g of final) {
  add("### "+g.cat+"（"+g.items.length+" 个）");
  add("");
  add("| # | 平台 | 网址 | 实测状态 | 项目信号 | 价格信号 |");
  add("|---|---|---|---|---|---|");
  for (const it of g.items) {
    const d = detail[String(it.host).toLowerCase()] || {};
    const st = String(it.status||d.status||"");
    const tag = st.includes("有活有价") ? "✅有活+有价" : st.includes("有活") ? "✅有活" : "⚠️需登录";
    add("| "+globalIdx+" | **"+(it.name||it.host)+"** | "+it.host+" | "+tag+" | "+(d.projHits||it.proj||0)+" | "+(d.moneyHits||it.money||0)+" |");
    globalIdx++;
  }
  add("");
}

add("## 三、⭐⭐ 按门槛排序（先做哪些）");
add("");
add("| 门槛 | 平台类型 | 适合 |");
add("|---|---|---|");
add("| **🟢 极低（当天能干）** | Clickworker、Microworkers、Toloka、UserTesting、UserInterviews、Respondent、dScout | 无技能要求，注册即可接微任务/测试 |");
add("| **🟢 低（有基础技能）** | Fiverr、Freelancer.com、Codeur、Useme、Twine、Workana | 挂服务等客户，或投标 |");
add("| **🟡 中（要作品集）** | Contra、Toptal、Arc.dev、Lemon.io、Codeable、Crew、Superside | 需要审核或作品 |");
add("| **🟡 中（要技术）** | Bugcrowd、HackerOne、huntr、Immunefi、Algora、Gitcoin | 技术好可做，赏金高 |");
add("| **🟠 高（需资质）** | Mercor、Alignerr、Outlier、DataAnnotation | 需专业背景或英语面试 |");
add("");
add("## 四、⚠️ 实测不可用（别浪费时间）");
add("");
add("| 平台 | 原因 |");
add("|---|---|");
add("| **Upwork** | 403 反爬（但平台真实存在，需注册才能看活） |");
add("| **PeoplePerHour** | 返回空页（可能改版或需登录） |");
add("| **Guru** | 403 反爬 |");
add("| **猪八戒/一品威客/程序员客栈** | 全部需登录才显示项目，未登录是纯营销页 |");
add("| **Prolific/Appen/Scale AI** | 需注册审核 |");
add("");
add("**注意：这些不是「死站」，是「必须注册才能用」。你要用就得去注册。**");
add("");
add("## 五、⭐ 中文平台的诚实说明");
add("");
add("| 平台 | 实测 | 说明 |");
add("|---|---|---|");
add("| 一品威客 | ❌ 打不开 | 可能是 DNS 或临时故障，之前能访问 |");
add("| 猪八戒 | ⚠️ 需登录 | 未登录只显示营销页，**但我知道它真实存在且能接单** |");
add("| 程序员客栈 | ⚠️ 需登录 | 同上 |");
add("| 实现网 | ⚠️ 需登录 | 同上 |");
add("| 云沃客/开源众包 | ❌ 打不开 | 可能已关停 |");
add("");
add("**结论：中文接单平台大多数需要注册后才能看到项目，我这边无登录态抓不到。但它们确实存在。**");
add("");
add("## 六、数据来源");
add("");
add("| 文件 | 内容 |");
add("|---|---|");
add("| `_GIG50_CANDIDATES.json` | 91 个首批候选 |");
add("| `_GIG50_RESULT.json` | 91 个实测结果 |");
add("| `_GIG_EXTRA.json` | 41 个补充候选 |");
add("| `_GIG_EXTRA_RESULT.json` | 41 个实测结果 |");
add("| `_GIG50_CLEAN.json` | 筛选后可用清单 |");
add("");
add("## 七、数据局限");
add("");
add("| 局限 | 说明 |");
add("|---|---|");
add("| 无法验证「现在有多少活」 | HTTP 只能看页面有没有项目词，不能判断活多不多 |");
add("| 需登录的站看不到 | Upwork/猪八戒等必须注册 |");
add("| 单日快照 | 2026-10-21 一次实测 |");
add("| 未验证注册可行性 | 没实际注册过，有些站可能限制中国区 |");
add("");

await fs.writeFile(P2+"\\50个真实接单平台-实测版.md", rows.join("\n"), "utf8");
const st = await fs.stat(P2+"\\50个真实接单平台-实测版.md");
return { bytes: st.size, total, groups: final.map(g=>g.cat+":"+g.items.length) };
